import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, time, id) - max price first, then earliest time
    sell_heap = []  # (price, time, id) - min price first, then earliest time
    book = {}  # id -> [side, price, remaining_qty, time, active]
    time_counter = 0

    for order in orders:
        time_counter += 1
        if order[0] == 'cancel':
            _, oid = order
            if oid in book:
                book[oid][4] = False
            continue

        typ = order[0]
        if typ == 'limit' or typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty
        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            top_id = top[2]
            if top_id not in book or not book[top_id][4]:
                heapq.heappop(opp_heap)
                continue
            opp_price = book[top_id][1]
            opp_qty = book[top_id][2]
            if opp_qty <= 0:
                heapq.heappop(opp_heap)
                continue
            if side == 'buy':
                if price is not None and opp_price > price:
                    break
            else:
                if price is not None and opp_price < price:
                    break

            trade_qty = min(remaining, opp_qty)
            if side == 'buy':
                trades.append([oid, top_id, opp_price, trade_qty])
            else:
                trades.append([top_id, oid, opp_price, trade_qty])

            remaining -= trade_qty
            book[top_id][2] -= trade_qty
            if book[top_id][2] == 0:
                book[top_id][4] = False
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = [side, price, remaining, time_counter, True]
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, time_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, time_counter, oid))
        # ioc and market discard remainder; limit orders fully filled don't need to be added

    return trades

